{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    Args:
        rows: Iterable of mappings; may be a one-shot generator and may be empty.
        columns: Ordered iterable of unique string column names; may be a
            one-shot generator and may be empty.

    Returns:
        A str with the header followed by one record per row, using comma
        delimiters, CRLF record endings, minimal quoting with doubled quotes,
        and preserving embedded CR/LF and Unicode.

    Missing fields and None values are rendered as empty strings. Other values
    are rendered via str(value). Fields not listed in columns are ignored.
    Inputs are not mutated.

    Raises:
        ValueError: If column names are duplicated or are not strings.
    """
    if not isinstance(columns, (str, bytes)):
        try:
            column_list = list(columns)
        except TypeError:
            raise ValueError("columns must be an iterable of column names")
    else:
        raise ValueError("columns must be an iterable of column names")

    seen = set()
    for name in column_list:
        if not isinstance(name, str):
            raise ValueError("column names must be strings")
        if name in seen:
            raise ValueError("duplicate column name: {!r}".format(name))
        seen.add(name)

    lines = []

    def _record(values):
        fields = []
        for value in values:
            if value is None:
                text = ""
            elif isinstance(value, str):
                text = value
            else:
                text = str(value)
            if any(ch in text for ch in ("\r", "\n", '"', ",")):
                text = '"' + text.replace('"', '""') + '"'
            fields.append(text)
        return ",".join(fields)

    lines.append(_record(column_list))

    for row in rows:
        values = [row.get(name) for name in column_list]
        lines.append(_record(values))

    return "\r\n".join(lines) + "\r\n"
